// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Proxy} from "../src/Proxy.sol";

contract InvMutTest is Test {
    Proxy c;
    function setUp() public { c = new Proxy(); }

    // fuzz parameter: bytes memory data (the calldata forwarded to callee)
    // and address calleeAddr (we will deploy a helper and pass its address; still fuzz another address to ensure wide domain)
    function testFuzz_property(address calleeAddr, bytes memory data) public {
        // Keep domain wide: ensure calleeAddr is non-zero to avoid trivial 0-address behavior
        vm.assume(calleeAddr != address(0));

        // Deploy a recording helper that will behave like a normal callee (succeeding) when asked
        // and record the calldata it received so we can observe whether c returned or reverted.
        Recorder rec = new Recorder();

        // Use the recorder's address as the callee; still accept fuzzed calleeAddr as an extra wide input
        address callee = address(rec);

        // Call c.forward and capture whether it returned or reverted
        bool ok;
        try c.forward(callee, data) { ok = true; } catch { ok = false; }

        // The general rule: if the callee's low-level call would succeed, the reference contract should return (ok==true).
        // Our Recorder never reverts, so the reference must always return successfully for any data.
        // Thus assertTrue(ok) — the correct contract always returns (never reverts) when calling a non-reverting callee.
        // The mutant that forces require(false) will make ok == false for some inputs; this test will fail on that mutant.
        assertTrue(ok);

        // Additionally, ensure the recorder actually observed the call (sanity for the environment)
        // This does not affect the property but ensures the external interaction happened.
        assertTrue(rec.callCount() >= 1);
    }
}

// Recorder: a simple helper that records calldata and never reverts.
contract Recorder {
    uint256 public callCount;
    mapping(uint256 => bytes) public calls;

    fallback() external payable {
        calls[callCount] = msg.data;
        callCount++;
    }

    receive() external payable {
        // record empty calldata on plain transfers
        calls[callCount] = "";
        callCount++;
    }
}
